//! Golden parity for Carbune2020 / OnlineHTR featurization (ephemeris-ktg.8).
//!
//! Fixtures under `tests/fixtures/htr-carbune-parity/` were generated by
//! `scripts/gen_htr_carbune_parity_fixtures.py` (pure-Python when scipy is
//! unavailable). Expected features are also asserted inline in unit tests.

use ephemeris_core::{
    featurize_line, Color, Point, Stroke, StrokeId, StrokeLine, Tool, CARBUNE_POINTS_PER_UNIT,
};
use serde::Deserialize;
use std::path::PathBuf;

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/htr-carbune-parity")
}

#[derive(Debug, Deserialize)]
struct InkFixture {
    strokes: Vec<InkStroke>,
}

#[derive(Debug, Deserialize)]
struct InkStroke {
    t0_ms: u64,
    points: Vec<InkPoint>,
}

#[derive(Debug, Deserialize)]
struct InkPoint {
    x: f32,
    y: f32,
    t_ms: u32,
}

#[derive(Debug, Deserialize)]
struct ExpectedFeatures {
    features: Vec<[f32; 4]>,
}

fn load_line(name: &str) -> (StrokeLine, Vec<[f32; 4]>) {
    let dir = fixture_dir();
    let ink: InkFixture = serde_json::from_str(
        &std::fs::read_to_string(dir.join(format!("{name}.ink.json"))).expect("ink json"),
    )
    .expect("parse ink");
    let expected: ExpectedFeatures = serde_json::from_str(
        &std::fs::read_to_string(dir.join(format!("{name}.expected_features.json")))
            .expect("features json"),
    )
    .expect("parse features");

    let strokes: Vec<Stroke> = ink
        .strokes
        .iter()
        .map(|s| Stroke {
            id: StrokeId::new(),
            tool: Tool::Pen,
            color: Color::BLACK,
            base_width: 2.0,
            points: s
                .points
                .iter()
                .map(|p| Point::new(p.x, p.y, 0.5, 0.0, p.t_ms))
                .collect(),
            t0_ms: s.t0_ms,
        })
        .collect();

    let mut min_x = f32::INFINITY;
    let mut min_y = f32::INFINITY;
    let mut max_x = f32::NEG_INFINITY;
    let mut max_y = f32::NEG_INFINITY;
    for s in &strokes {
        for p in &s.points {
            min_x = min_x.min(p.x);
            min_y = min_y.min(p.y);
            max_x = max_x.max(p.x);
            max_y = max_y.max(p.y);
        }
    }
    let line = StrokeLine {
        strokes,
        x: min_x,
        y: min_y,
        width: (max_x - min_x).max(1.0),
        height: (max_y - min_y).max(1.0),
    };
    (line, expected.features)
}

fn assert_features_close(got: &[[f32; 4]], expected: &[[f32; 4]]) {
    assert_eq!(got.len(), expected.len(), "timestep count mismatch");
    for (t, (g, e)) in got.iter().zip(expected.iter()).enumerate() {
        for i in 0..4 {
            assert!(
                (g[i] - e[i]).abs() < 1e-3,
                "t={t} ch={i}: got {} expected {}",
                g[i],
                e[i]
            );
        }
    }
}

#[test]
fn stroke_htr_golden_real_t0_parity() {
    let (line, expected) = load_line("two-stroke-short-real-t0");
    let got = featurize_line(&line, CARBUNE_POINTS_PER_UNIT);
    assert_features_close(&got, &expected);
}

#[test]
fn stroke_htr_golden_synth_t0_parity() {
    let (line, expected) = load_line("two-stroke-short-synth-t0");
    let got = featurize_line(&line, CARBUNE_POINTS_PER_UNIT);
    assert_features_close(&got, &expected);
}

/// Decode the golden sample with the real OnlineHTR model when present.
///
/// Run with: `EPHEMERIS_HTR_MODEL_DIR=... cargo test -p ephemeris-core --features htr \
///   stroke_htr_golden_model_decode -- --ignored`
#[test]
#[ignore = "requires OnlineHTR model weights on disk"]
fn stroke_htr_golden_model_decode_when_model_present() {
    #[cfg(not(feature = "htr"))]
    {
        eprintln!("htr feature disabled — skip model decode");
    }
    #[cfg(feature = "htr")]
    {
        use ephemeris_core::{StrokeHtrTranscriber, Transcriber};
        let dir = std::env::var("EPHEMERIS_HTR_MODEL_DIR")
            .ok()
            .map(PathBuf::from)
            .or_else(|| {
                let candidates = [
                    PathBuf::from("models/htr"),
                    PathBuf::from("models/stroke-htr"),
                    PathBuf::from("data/htr"),
                ];
                candidates
                    .into_iter()
                    .find(|p| p.join("model.onnx").is_file() || p.join("model.rten").is_file())
            });
        let Some(dir) = dir else {
            panic!(
                "set EPHEMERIS_HTR_MODEL_DIR to a directory with model.onnx/rten \
                 (or place weights under models/htr)"
            );
        };
        let htr = StrokeHtrTranscriber::from_parts(true, Some(dir));
        assert!(
            htr.model_available(),
            "model files missing in {:?}",
            htr.model_dir
        );
        let (line, _) = load_line("two-stroke-short-real-t0");
        let spans = htr.transcribe(&line.strokes).expect("transcribe");
        // Synthetic short strokes are not real handwriting; just ensure the
        // pipeline runs without panic when the model is present.
        eprintln!("golden decode spans: {spans:?}");
    }
}
